#generated by Claude
"""Baseline: causal bandpass -> CSP -> smoothed log band power -> one logistic regression per event.

Interface used by main.py:
    run(subject, train_series, val_series) -> (preds, info)
    preds: {series: array (N, 6)} of event probabilities at every sample (500 Hz)
"""
import numpy as np
from scipy.signal import lfilter
from sklearn.linear_model import LogisticRegression
from mne.decoding import CSP

import config
from data_loading import load_series
from preprocess import bandpass, bandpass_macs

N_FILTERS = 4
SMOOTH_WIN = 250                 # 0.5 s causal window at 500 Hz
SUBSAMPLE = 10                   # train on every 10th sample; to speed up training and reduce correlation between samples
EPOCH_LEN = 2 * config.FS        # CSP epochs: 2 s after / before HandStart to train the spatial filters; the original script used 1 s, but 2 s gives more samples and is still short enough to avoid contamination from other events


def _features(Xf, W):
    """Xf: filtered (32, N). Returns (4, N): log of causally smoothed CSP power."""
    power = (W @ Xf) ** 2 #Projects the 32-channel EEG data through the spatial filters $W$ and squares it to get signal power
    smooth = lfilter(np.ones(SMOOTH_WIN), 1.0, power, axis=1)
    return np.log(np.maximum(smooth, 1e-30)) #logreg performms better with normalized features, and the log of power is a common feature in EEG analysis. The maximum with 1e-30 avoids taking the log of zero, which would be undefined.


def _csp_epochs(Xf, Y): #cuts out epochs around HandStart events to train the CSP filters
    onsets = np.where(np.diff(Y[0], prepend=0) == 1)[0]     # HandStart rising edges
    during, rest = [], []
    for o in onsets:
        if o - EPOCH_LEN >= 0 and o + EPOCH_LEN <= Xf.shape[1]:
            during.append(Xf[:, o:o + EPOCH_LEN])
            rest.append(Xf[:, o - EPOCH_LEN:o])
    return during, rest


def run(subject, train_series, val_series):
    train, during, rest = [], [], []
    for s in train_series:
        X, Y = load_series(subject, s)
        Xf = bandpass(X * 1e-6)                    # microvolts to volts, as in the original script
        d, r = _csp_epochs(Xf, Y)
        during += d
        rest += r
        train.append((Xf, Y))

    X_ep = np.stack(during + rest)
    y_ep = np.array([1] * len(during) + [-1] * len(rest))
    csp = CSP(n_components=N_FILTERS, reg="oas")
    csp.fit(X_ep, y_ep)
    W = csp.filters_[:N_FILTERS]

    F = np.concatenate([_features(Xf, W) for Xf, _ in train], axis=1)
    L = np.concatenate([Y for _, Y in train], axis=1)
    clfs = []
    for i, name in enumerate(config.EVENTS):
        clf = LogisticRegression(max_iter=1000)
        clf.fit(F[:, ::SUBSAMPLE].T, L[i, ::SUBSAMPLE])
        clfs.append(clf)

    preds = {}
    for s in val_series:
        X, _ = load_series(subject, s)
        Fv = _features(bandpass(X * 1e-6), W)
        preds[s] = np.stack([c.predict_proba(Fv.T)[:, 1] for c in clfs], axis=1)

    n_events = len(config.EVENTS)
    params = N_FILTERS * config.N_CHANNELS + n_events * (N_FILTERS + 1)
    macs_per_sample = (config.N_CHANNELS * bandpass_macs()          # bandpass
                       + N_FILTERS * config.N_CHANNELS              # CSP projection
                       + n_events * N_FILTERS)                      # logistic regressions
    info = {"params": params,
            "stored_bytes": params * 4,                             # float32 assumed
            "ops_per_second": macs_per_sample * config.FS}          # smoothing and log excluded
    return preds, info